-- Esquema inicial de referencia. Ejecutar manualmente en desarrollo.
CREATE TABLE IF NOT EXISTS categories (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, slug varchar(120) NOT NULL UNIQUE, name varchar(150) NOT NULL, description text NOT NULL);
CREATE TABLE IF NOT EXISTS topics (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id integer NOT NULL REFERENCES categories(id), slug varchar(180) NOT NULL UNIQUE, title varchar(180) NOT NULL, body text NOT NULL, author_name varchar(80) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_topics_category_id ON topics(category_id);
CREATE INDEX IF NOT EXISTS ix_topics_published_created ON topics(created_at DESC) WHERE published = true;
INSERT INTO categories(slug,name,description) VALUES ('herramientas-ia','Herramientas de IA','Comparativas, novedades y recomendaciones de herramientas de inteligencia artificial.'),('programacion-ia','Programación e IA','Python, APIs, agentes, modelos locales y proyectos de código abierto.'),('tutoriales','Tutoriales y aprendizaje','Guías prácticas para aprender y utilizar inteligencia artificial.'),('debates','Debates sobre IA','Preguntas, opiniones y conversaciones sobre el futuro de la inteligencia artificial.') ON CONFLICT(slug) DO NOTHING;
